# 料理名・写真ファイル名・材料（すべて1人分）・作り方をここで編集できます。
# 画像が未配置の場合はブラウザで代替表示になります。

def recipe(name, category, minutes, ingredients, steps, image=None, description='少ない材料で作れるお手軽レシピ。'):
    return dict(name=name, category=category, minutes=minutes, ingredients=ingredients,
                steps=steps, image=image, description=description)

